function goToCandRetosTab(){
  switchCandTab('common');
  setTimeout(function(){
    const grid=document.getElementById('commonExGrid');
    if(grid)grid.scrollIntoView({behavior:'smooth',block:'start'});
  },80);
}
/** Cambia de página en el panel del candidato (menú lateral, 10-paneles-y-pagos.js). */
function switchCandTab(tab){tpPanelIr('cand',tab);}

function updateCandProfile(){
  const completed=candidateProfile.completedCommon;
  // Sin nota media global: se cuentan las skills demostradas en «Bueno» o más.
  const demostradas=Object.values(candidateProfile.skills).filter(d=>d&&d.unlocked);
  const buenas=demostradas.filter(d=>tpBanda(d.score).nivel>=3).length;
  document.getElementById('cDashCompleted').textContent=completed.length;
  document.getElementById('cDashScore').textContent=demostradas.length?String(buenas):'—';
  // Posición real en el pool (16-pool-real.js), no un tramo inventado por nota.
  document.getElementById('cDashRank').textContent=(window.TPRanking&&TPRanking.posicionTexto())||'—';
  document.getElementById('spGlobalScore').textContent=demostradas.length||'—';
  // Cabecera: el alias con el que te ven las empresas (antes «AC · Candidato
  // anónimo» escrito a mano, igual para todo el mundo).
  const alias=(window.TPRanking&&TPRanking.miAlias())||null;
  const av=document.getElementById('spAvatar'),meta=document.getElementById('spMeta');
  if(av)av.textContent=alias?alias.replace(/^Candidato #/,'').slice(0,2):'—';
  if(meta)meta.textContent=alias
    ?'Así te ven las empresas: '+alias+' · '+(completed.length?completed.length+(completed.length===1?' reto completado':' retos completados'):'completa retos para desbloquear skills')
    :'Sin cuenta: inicia sesión para guardar tu progreso y aparecer en el pool';
  const softSkills=[];const sectorSkills=[];
  for(const[name,data] of Object.entries(candidateProfile.skills)){
    const ce=COMMON_EXERCISES.find(c=>c.skill===name);
    const cat=ce?.category||'soft';
    if(cat==='soft')softSkills.push({name,data});else sectorSkills.push({name,data});
  }
  // Pendientes: solo el nombre. Las demostradas van en sus dos bloques con banda y nota.
  function renderSG(skills){
    return skills.map(({name})=>'<div class="sp-skill-item locked"><div class="sp-skill-name">'+escHtml(typeof tpSkillNombre==='function'?tpSkillNombre(name):name)+'</div><div class="tp-bloque-vacio">Pendiente</div></div>').join('');
  }
  const uS=softSkills.filter(s=>s.data.unlocked);const lS=softSkills.filter(s=>!s.data.unlocked);
  const uSe=sectorSkills.filter(s=>s.data.unlocked);const lSe=sectorSkills.filter(s=>!s.data.unlocked);
  let html='';
  if(uS.length+uSe.length>0){
    html+='<div class="u-fs-micro u-fw-700 u-c-emerald-600 u-tt-uppercase u-ls-_08em u-mb-8">Skills desbloqueados ('+(uS.length+uSe.length)+')</div>';
    html+='<div class="u-mb-16">'+tpBloquesSkills([...uS,...uSe].map(({name,data})=>({n:name,v:data.score,verified:!!data.verified})),{conNota:true})+'</div>';
  }
  const totalLocked=lS.length+lSe.length;
  if(totalLocked>0){
    const startHidden=totalLocked>12;
    html+='<button type="button" class="btn btn-outline btn-sm sp-pending-toggle" aria-expanded="'+(startHidden?'false':'true')+'" onclick="var g=document.getElementById(\'lockedSkillsGrid\');if(!g)return;var hidden=(g.style.display===\'none\');g.style.display=hidden?\'grid\':\'none\';this.setAttribute(\'aria-expanded\',hidden?\'true\':\'false\');this.textContent=hidden?\'Ocultar skills pendientes ▴\':\'Ver '+totalLocked+' skills pendientes ▾\'">'+(!startHidden?'Ocultar skills pendientes ▴':'Ver '+totalLocked+' skills pendientes ▾')+'</button>';
    html+='<div class="sp-skills-grid" id="lockedSkillsGrid" style="display:'+(startHidden?'none':'grid')+'">'+renderSG([...lS,...lSe])+'</div>';
  }
  document.getElementById('spSkillsGrid').innerHTML=html;
  const matches=getJobMatches();
  document.getElementById('cDashMatches').textContent=matches.filter(m=>m.matchScore===100).length;

  const cta=document.getElementById('candZeroRetosCta');
  const foot=document.getElementById('candProfileFootnote');
  if(cta){
    if(completed.length===0){
      cta.style.display='block';
      if(foot)foot.style.display='none';
      const ver=document.getElementById('candBtnVerRetos');
      const sugBtn=document.getElementById('candBtnStartSuggested');
      if(ver)ver.onclick=function(){goToCandRetosTab();};
      const sug=COMMON_EXERCISES.find(function(c){return !candidateProfile.completedCommon.find(function(x){return x.id===c.id;});});
      if(sugBtn){
        if(sug){
          sugBtn.style.display='inline-flex';
          sugBtn.textContent='Empezar: '+sug.title;
          sugBtn.onclick=function(){openCommonEx(sug.id);};
        }else{
          sugBtn.style.display='none';
        }
      }
    }else{
      cta.style.display='none';
      if(foot)foot.style.display='block';
    }
  }
}

let _dashExCat='all';

function renderCommonExercises(filter='',cat='all'){
  let list=COMMON_EXERCISES;
  // Category filter
  if(cat==='soft')list=list.filter(ce=>ce.category==='soft');
  else if(cat==='sector')list=list.filter(ce=>ce.category==='sector');
  else if(cat==='done')list=list.filter(ce=>candidateProfile.completedCommon.find(c=>c.id===ce.id));
  else if(cat==='pending')list=list.filter(ce=>!candidateProfile.completedCommon.find(c=>c.id===ce.id));
  // Text search
  if(filter){
    const q=filter.toLowerCase();
    list=list.filter(ce=>(ce.title+' '+ce.desc+' '+(ce.searchTerms||'')+' '+ce.skill).toLowerCase().includes(q));
  }
  let html='';
  if(!list.length){
    html='<div class="u-ta-center u-p-24 u-c-slate-400 u-grid-column-1--1"><p>No hay retos que coincidan con tu búsqueda.</p></div>';
  }else{
    list.forEach(ce=>{
      const done=candidateProfile.completedCommon.find(c=>c.id===ce.id);
      const catBadge=ce.category==='sector'?`<span class="cex-tag u-bg-blue-100 u-c-blue-500 u-b-1-solid-rgba-59-130-246-_15">Sector</span>`:`<span class="cex-tag universal">Universal</span>`;
      html+=`<div class="common-ex-card ${done?'completed':''}" onclick="openCommonEx('${ce.id}')"><span class="cex-icon">${tpMonograma(ce.title,ce.category)}</span><div class="cex-title">${ce.title}</div><div class="cex-desc">${ce.desc}</div><div class="cex-meta">${catBadge}${ce.tags.filter(t=>t!=='Universal'&&t!=='Sector').map(t=>`<span class="cex-tag">${t}</span>`).join('')}${done?`<span class="cex-tag u-bg-emerald-50 u-c-emerald-600 u-b-1-solid-emerald-100">✓ ${done.score}/100</span>`:''}</div></div>`;
    });
  }
  document.getElementById('commonExGrid').innerHTML=html;
}

function filterDashCommonEx(){
  const q=document.getElementById('dashExSearch')?.value||'';
  document.getElementById('dashExClear').classList.toggle('show',q.length>0);
  renderCommonExercises(q,_dashExCat);
}

function setDashExCat(cat,btn){
  _dashExCat=cat;
  document.querySelectorAll('#dashExFilters .filter-btn').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active');
  filterDashCommonEx();
}

function openCommonEx(id){
  const ce=COMMON_EXERCISES.find(c=>c.id===id);
  if(!ce)return;
  activeJob={id:id,title:ce.title,sector:'Universal',badge:'jb-cognitive',desc:ce.desc,tags:ce.tags,_isCommon:true,_skill:ce.skill};
  currentEx=0;exResults={};_exState={};
  document.getElementById('jmBadge').className='job-badge';
  document.getElementById('jmBadge').textContent='RETO COMÚN';
  document.getElementById('jmBadge').style.cssText='background:var(--emerald-50);color:var(--emerald-600);border:1px solid var(--emerald-100)';
  document.getElementById('jmTitle').textContent=ce.title;
  document.getElementById('jmDesc').textContent=ce.desc;
  const el=ce.exercises;
  document.getElementById('jmProgress').innerHTML=el.map((_,i)=>`<div class="prog-dot${i===0?' active':''}" id="pd${i}"></div>`).join('')+`<span class="prog-lbl">${el.length} ejercicios</span>`;
  document.getElementById('exNav').innerHTML=el.map((e,i)=>`<button class="ex-tab${i===0?' active':''}" onclick="switchEx(${i})"><span class="ex-tab-num">${e.num}</span>${e.title.length>18?e.title.slice(0,18)+'…':e.title}</button>`).join('');
  renderEx(el,0);
  document.getElementById('jobModal').classList.add('open');document.getElementById('jobModal').scrollTop=0;
}

function getJobMatches(){
  // Cada skill se compara con su propio mínimo (20-requisitos.js); las ofertas
  // antiguas, con su nivel único, cuentan todas como imprescindibles.
  return JOBS.map(j=>{
    const reqs=tpReqDeOferta(j);
    const notas={};reqs.forEach(r=>{const sk=candidateProfile.skills[r.skill];if(sk?.unlocked)notas[r.skill]=sk.score;});
    const enc=tpReqEncaje(reqs,notas,null);
    const has=enc.estados.filter(e=>e.estado==='cumple').map(e=>e.skill);
    const missing=enc.estados.filter(e=>e.estado!=='cumple').map(e=>e.skill);
    const imp=enc.imprescindibles;
    const matchScore=reqs.length?Math.round((imp.total?imp.cumple/imp.total:has.length/reqs.length)*100):10;
    const co=COMPANIES.find(c=>c.id===j.company);
    return{...j,matchScore,has,missing,enc,companyName:co?.name||'',companyLogo:co?.logo||''};
  }).sort((a,b)=>a.enc.grupo-b.enc.grupo||b.matchScore-a.matchScore);
}

function renderJobMatches(){
  const matches=TPEmpleo.filtrar(getJobMatches());
  const sinRetos=candidateProfile.completedCommon.length===0;
  const est=typeof TPOfertas!=='undefined'?TPOfertas.estado:'ok';
  const irRetos="switchCandTab('common')";
  let html=TPEmpleo.toolbar();
  // Antes, sin ningún reto hecho no se enseñaba ninguna oferta. Ahora se ven
  // siempre; lo que falta hasta el primer reto es el % de encaje.
  if(!JOBS.length){
    html+=est==='error'?tpVacio({error:true,icono:'alert',titulo:'No se han podido cargar las ofertas',texto:'Es un problema nuestro, no de tu cuenta. Vuelve a intentarlo en unos minutos.',acciones:[{txt:'Reintentar',accion:'TPOfertas.cargar()'}]})
      :(est==='cargando'||est==='sin cargar')?tpEsqueleto(4)
      :tpVacio({icono:'building',titulo:'Todavía no hay ofertas publicadas',texto:'Cuando una empresa publique una oferta, aparecerá aquí con tu % de encaje.',acciones:sinRetos?[{txt:'Mientras, haz tu primer reto',accion:irRetos,tipo:'btn-primary'}]:[]});
    document.getElementById('candMatchesList').innerHTML=html;
    return;
  }
  if(sinRetos)html+=tpSiguiente({icono:'target',titulo:'Haz tu primer reto para ver tu % de encaje',sub:'Ya puedes ver todas las ofertas; el encaje se calcula con tus skills verificadas.',boton:'Ir a los retos',accion:irRetos});
  matches.forEach(m=>{
    const reqLevel=m.requiredLevel||'basico';
    const imp=m.enc.imprescindibles;
    const allMet=m.enc.grupo<=2&&m.enc.estados.length>0;
    const cls=sinRetos?'match-low':allMet?'match-high':m.has.length>0?'match-mid':'match-low';
    const pct=m.matchScore;
    const levelCls='level-'+reqLevel;
    const levelLabel=reqLevel==='avanzado'?'Avanzado':reqLevel==='intermedio'?'Intermedio':'Básico';
    html+=`<div class="match-card" onclick="openJob('${escHtml(m.id)}')">
      <div class="match-score-ring ${cls}">${sinRetos?'—':pct+'%'}</div>
      <div class="match-info">
        <h4>${escHtml(m.title)} <span class="level-badge ${levelCls} tp-va-medio">${levelLabel}</span></h4>
        <div class="match-company">${escHtml(m.companyName)}</div>
        ${tpCondChips(m)}
        <div class="tp-match-skills">${m.enc.estados.map(e=>{const ok=e.estado==='cumple';const min=TP_REQ_MINIMOS[e.minimo].txt;return`<span class="job-tag tp-skill-req ${ok?'ok':'falta'}${e.peso==='imprescindible'?' imp':''}" title="${e.peso==='imprescindible'?'Imprescindible':'Valorable'} · mínimo ${min}">${ok?'✓ ':''}${escHtml(tpSkillNombre(e.skill))}</span>`;}).join('')}</div>
      </div>
      <div class="match-why">${sinRetos?'Ver oferta →':allMet?'✓ Cumples las imprescindibles':imp.total?imp.cumple+' de '+imp.total+' imprescindibles':m.has.length+' de '+m.enc.estados.length+' skills'}</div>
    </div>`;
  });
  if(!matches.length)html+=tpVacio({icono:'search',titulo:'Ninguna oferta cumple esos filtros',texto:'Prueba a quitar algún filtro de jornada o modalidad.'});
  document.getElementById('candMatchesList').innerHTML=html;
}

